#include <Arduino.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

int Led1 = 15;
int Led2 = 4;
int Led3 = 16;
int Led4 = 17;
int Led5 = 5;
int Led6 = 18;

int ButtonC = 19;
int ButtonR = 13;

int Count = 0;
int Clicks = 0;

void setup() {
  pinMode(Led1, OUTPUT);
  pinMode(Led2, OUTPUT);
  pinMode(Led3, OUTPUT);
  pinMode(Led4, OUTPUT);
  pinMode(Led5, OUTPUT);
  pinMode(Led6, OUTPUT);
  pinMode(ButtonC, INPUT_PULLUP);
  pinMode(ButtonR, INPUT_PULLUP);

  Wire.begin();
  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("Press 1. button");  

  Serial.begin(115200);
  Serial.println("Program initiated");
}

void Display(int number, int click) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Progress: " + String(number));
  lcd.setCursor(0, 1);
  lcd.print("Clicks: " + String(click));
  delay(50);
}

void Turn() {
  if (Count == 1) {
    digitalWrite(Led1, HIGH);
    Display(1, Clicks);
  }
  if (Count == 2) {
    digitalWrite(Led2, HIGH);
    Display(2, Clicks);
  }
  if (Count == 3) {
    digitalWrite(Led3, HIGH);
    Display(3, Clicks);
  }
  if (Count == 4) {
    digitalWrite(Led4, HIGH);
    Display(4, Clicks);
  }
  if (Count == 5) {
    digitalWrite(Led5, HIGH);
    Display(5, Clicks);
  }
  if (Count == 6) {
    digitalWrite(Led6, HIGH);
    Display(6, Clicks);
  }
  if (Count == 0) {
    digitalWrite(Led1, LOW);
    digitalWrite(Led2, LOW);
    digitalWrite(Led3, LOW);
    digitalWrite(Led4, LOW);
    digitalWrite(Led5, LOW);
    digitalWrite(Led6, LOW);
    Display(0, Clicks);
  }
  delay(50);
}

int LedCount = 6;
void Load() {
  if (digitalRead(ButtonC) == LOW) {
    delay(50);
    if (Count < LedCount) {
      Count++;
      Turn();
    } else {
      Count = 0;
      Clicks++;
      Turn();
    }
    while (digitalRead(ButtonC) == LOW) {

    }
    delay(50);
  }
}

void Reset() {
  if (digitalRead(ButtonR) == LOW) {
    delay(50);
    Clicks = 0;
    Count = 0;
    Display(0, 0);

    while (digitalRead(ButtonR) == LOW) {

    }

    delay(50);
  }
}

void loop() {
  Load();
  Reset();
}
